  case TargetSignal::kRequiresAdministrator: return &facts.requires_administrator;
  case TargetSignal::kTokenElevated: return &facts.token_elevated;
  case TargetSignal::kTokenOtherUser: return &facts.token_other_user;
  case TargetSignal::kTokenOtherSession: return &facts.token_other_session;
  case TargetSignal::kTokenProtected: return &facts.token_protected;
  case TargetSignal::kTokenUiAccess: return &facts.token_ui_access;
  case TargetSignal::kTokenIntegrityAboveSelf: return &facts.token_integrity_above_self;
  case TargetSignal::kTokenAppContainer: return &facts.token_app_container;
  case TargetSignal::kPackaged: return &facts.packaged;
  case TargetSignal::kPackageDevelopmentMode: return &facts.package_development_mode;
  case TargetSignal::kOwnDescendant: return &facts.own_descendant;
  case TargetSignal::kDescendantShell: return &facts.descendant_shell;
